export function CapabilityIcon({ name, className }) {
  // For dataverse, use the imported colored SVG as an image
  if (name === "dataverse") {
    return (
      <img
        src={DataverseIcon}
        alt="Dataverse"
        className={className}
        aria-hidden="true"
        style={{ width: "24px", height: "24px", display: "block" }}
      />
    );
  }

  return (
    <svg
      viewBox="0 0 32 32"
      width="24"
      height="24"
      className={className}
      fill="none"
      stroke="currentColor"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      style={{ display: "block" }}
    >
      <g transform="translate(4 4) scale(0.75)">
        {paths[name] ?? null}
      </g>
    </svg>
  );
}
